function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}

function slug(value, fallback = '') {
  return String(value || fallback || '').trim();
}

const body = $json.body || {};

const avatar = slug(body.avatar);
const scene = slug(body.scene);
const status = slug(body.status || 'generated');
const limit = Math.min(Number(body.limit || 50), 100);

const slugRegex = /^[a-z0-9][a-z0-9-]*$/i;

if (!slugRegex.test(avatar)) {
  return {
    json: {
      ok: false,
      skipQuery: true,
      error: 'avatar is required and must be slug-like',
      request: { avatar, scene, status }
    }
  };
}

let where = `
WHERE ga.avatar = ${sql(avatar)}
`;

if (scene && slugRegex.test(scene)) {
  where += `
  AND ga.scene = ${sql(scene)}
`;
}

if (status && slugRegex.test(status)) {
  where += `
  AND ga.status = ${sql(status)}
`;
}

const query = `
SELECT
  ga.generated_asset_id,
  ga.job_id,
  ga.asset_id,
  ga.avatar,
  ga.scene,
  ga.asset_type,
  ga.status,
  ga.review_notes,
  ga.metadata,
  ga.approved_at,
  ga.rejected_at,
  ga.created_at,
  ga.updated_at,
  car.bucket,
  car.object_path,
  car.mime_type,
  car.status AS registry_status,
  car.is_canonical,
  'http://192.168.0.194:9000' || '/' || car.bucket || '/' || car.object_path AS url
FROM generated_assets ga
LEFT JOIN canonical_asset_registry car
  ON car.asset_id = ga.asset_id::text
${where}
ORDER BY ga.created_at DESC
LIMIT ${limit};
`;

return {
  json: {
    ok: true,
    skipQuery: false,
    query
  }
};
